186	     let opened = false;
187	+    let handler: ((m: ServerMsg) => void) | null = null;
188	+    const pending: ServerMsg[] = [];   // tin tới trước khi người dùng gán onMessage (máy chủ gửi lobby ngay khi nhận kết nối) được giữ lại, không mất
189	     const tm = setTimeout(() => { if (!opened) { try { ws.close(); } catch (e) { /* bỏ qua */ } reject(new Error('timeout')); } }, timeoutMs);
190	     const t: Transport = {
191	       send: m => { if (ws.readyState === 1) ws.send(JSON.stringify(m)); },
192	       close: () => { try { ws.close(); } catch (e) { /* bỏ qua */ } },
193	-      onMessage: () => {},
194	+      get onMessage() { return handler as (m: ServerMsg) => void; },
195	+      set onMessage(fn: (m: ServerMsg) => void) { handler = fn; while (pending.length) fn(pending.shift() as ServerMsg); },
196	       onClose: () => {}
197	     };
198	     ws.onopen = () => { opened = true; clearTimeout(tm); resolve(t); };
199	     ws.onmessage = ev => {
