205	     ws.onerror = () => { if (!opened) { clearTimeout(tm); reject(new Error('ws error')); } };
206	     ws.onclose = () => { clearTimeout(tm); if (!opened) reject(new Error('closed')); else t.onClose(); };
207	   });
208	 }
