215	+/* ===== Dù lượn nhiều người: điều phối phía khách =====
216	+   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), nhãn tên và danh sách người bay.
217	+   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
218	+import { camera } from '../../core/renderer';
219	+import { CONFIG } from '../../config';
220	+import { t, onChange as onLang } from '../../i18n';
221	+import { exConnect } from './client';
222	+import { MultiSession } from './session';
223	+import { exRemotes } from './remote';
224	+import { exLabelsUpdate, exLabelsClear } from './labels';
225	+import type { GliderState } from '../flight';
226	+
227	+const M = CONFIG.explore.multi;
228	+let session: MultiSession | null = null;
229	+let sentAt = -1e9;
230	+let rosterKey = '';
231	+
232	+/* Danh sách người bay ở góc màn hình: đầu "Đang bay n/5", mỗi người một dòng có chấm màu theo slot; dùng textContent */
233	+function renderRoster(): void {
234	+  const box = document.getElementById('exMpRoster');
235	+  if (!box) return;
236	+  const flyers = session ? session.flyers : [];
237	+  const head = t('exMpFlying', { n: flyers.length });
238	+  const key = flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + (session ? session.mySlot : -1) + '#' + head;
239	+  if (key === rosterKey) return;
240	+  rosterKey = key;
241	+  box.hidden = !session || session.phase === 'solo';
242	+  box.textContent = '';
243	+  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
244	+  for (const f of flyers) {
245	+    const row = document.createElement('div'); row.className = 'ex-mp-row' + (session && f.slot === session.mySlot ? ' me' : '');
246	+    const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
247	+    const nm = document.createElement('span'); nm.textContent = f.name;
248	+    row.append(dot, nm); box.appendChild(row);
249	+  }
250	+}
251	+
252	+export const exMulti = {
253	+  /* Địa chỉ máy chủ: ?multi= nếu có; ?test không có multi= thì rỗng (không mở mạng); còn lại cấu hình */
254	+  url(): string {
255	+    const q = new URLSearchParams(location.search);
256	+    const u = q.get('multi');
257	+    if (u !== null) return u;
258	+    return q.has('test') ? '' : M.url;
259	+  },
260	+  get session(): MultiSession | null { return session; },
261	+  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test
262	+
263	+  /* Mở phiên; onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
264	+  begin(onReady: () => void): boolean {
265	+    const url = exMulti.url();
266	+    if (!url || session) return false;
267	+    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs));
268	+    let ready = false;
269	+    s.onPos = f => exRemotes.onPos(f, performance.now());
270	+    s.onChange = () => {
271	+      exRemotes.sync(s.flyers, s.mySlot);
272	+      if (s.phase === 'solo') exLabelsClear();
273	+      renderRoster();
274	+      exMulti.onChange();
275	+      if (!ready) { ready = true; onReady(); }
276	+    };
277	+    s.open();
278	+    return true;
279	+  },
280	+
281	+  /* Mỗi khung khi đang bay: dù người khác, nhãn, gửi vị trí sendHz lần/s */
282	+  update(_dt: number, nowMs: number, state: GliderState | null): void {
283	+    if (!session) return;
284	+    exRemotes.update(nowMs);
285	+    exLabelsUpdate(camera, exRemotes, nowMs);
286	+    if (state && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
287	+      sentAt = nowMs;
288	+      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
289	+      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank));
290	+    }
291	+  },
292	+
293	+  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
294	+  watchState(): GliderState | null {
295	+    return session && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
296	+  }
297	+};
