300	diff --git a/src/explore/multi/labels.ts b/src/explore/multi/labels.ts
301	new file mode 100644
302	index 0000000..1732c51
303	--- /dev/null
304	+++ b/src/explore/multi/labels.ts
305	@@ -0,0 +1,55 @@
306	+/* ===== Dù lượn nhiều người: nhãn tên nổi dưới cánh dù người khác =====
307	+   Một div cho mỗi slot trong #exMpLabels. Điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù), ẩn khi sau camera hoặc slot chưa hiện.
308	+   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
309	+import * as THREE from 'three';
310	+import { CONFIG } from '../../config';
311	+import type { exRemotes } from './remote';
312	+
313	+const M = CONFIG.explore.multi;
314	+interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
315	+let labs: Lab[] | null = null;
316	+const _v = new THREE.Vector3();
317	+
318	+function init(): Lab[] | null {
319	+  const box = document.getElementById('exMpLabels');
320	+  if (!box) return null;
321	+  return Array.from({ length: M.slots }, () => {
322	+    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
323	+    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
324	+  });
325	+}
326	+
327	+// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
328	+const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;
329	+
330	+export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number): void {
331	+  if (!labs && !(labs = init())) return;
332	+  const w = window.innerWidth, h = window.innerHeight;
333	+  for (let i = 0; i < labs.length; i++) {
334	+    const L = labs[i], st = remotes.slotState(i);
335	+    let vis = false;
336	+    if (st) {
337	+      _v.set(st.pos.x, st.pos.y - M.labelBelow, st.pos.z).applyMatrix4(camera.matrixWorldInverse);
338	+      if (-_v.z > 0.1) {   // trước camera
339	+        _v.applyMatrix4(camera.projectionMatrix);
340	+        const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
341	+        if (px > -80 && px < w + 80 && py > -40 && py < h + 40) {
342	+          vis = true;
343	+          if (nowMs - L.tMs >= 200) {
344	+            L.tMs = nowMs;
345	+            const txt = `${remotes.name(i)} · ${dist(Math.hypot(st.pos.x - camera.position.x, st.pos.y - camera.position.y, st.pos.z - camera.position.z))}`;
346	+            if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
347	+          }
348	+          if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
349	+        }
350	+      }
351	+    }
352	+    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
353	+  }
354	+}
355	+
356	+/* Ẩn hết nhãn (rời phòng) */
357	+export function exLabelsClear(): void {
358	+  if (!labs) return;
359	+  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
360	+}
