703	+// Dù chính đứng yên ở BASE, hướng +X; bot bay tại chỗ phía trước, hơi lệch hai bên
704	+const BASE = { x: 500, y: 150, z: 100 };
705	+function bot(name, ox, oz) {
706	+  const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
707	+  const b = { ws, timer: null };
708	+  ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name }));
709	+  ws.onmessage = (e) => {
710	+    if (JSON.parse(e.data).t === 'joined' && !b.timer) b.timer = setInterval(() => ws.send(JSON.stringify({ t: 'pos', x: BASE.x + ox, y: BASE.y + 5, z: BASE.z + oz, yaw: 0, bank: 0 })), 200);
711	+  };
712	+  b.close = () => { clearInterval(b.timer); try { ws.close(); } catch { /* bỏ qua */ } };
713	+  return b;
714	+}
715	+
716	+let srv, browser, page;
717	+const bots = [];
718	+try {
719	+  for (let i = 0; i < 120; i++) { if (/Ready on/.test(log)) break; await sleep(500); }
720	+  check('wrangler dev sẵn sàng', /Ready on/.test(log));
721	+  srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
722	+  browser = await launch();
723	+
724	+  // Mục 2 — không multi=: không mở WebSocket (cả ?explore=glider lẫn ?test thường)
725	+  for (const q of ['', '?explore=glider']) {
726	+    const P = await openApp(browser, srv.url + q);
