738	+  await page.evaluate(() => window.__app.multi.fly('Tester'));
739	+  await page.waitForFunction(() => window.__app.explore.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 });
740	+  const mine = await page.evaluate(() => window.__app.multi.session.mySlot);
741	+  check('vào phòng và bay với slot ' + mine, mine >= 0);
742	+  // Ghim dù chính tại BASE sau mỗi lần animate (rAF đăng ký sau chạy sau)
743	+  await page.evaluate((B) => {
744	+    const s = window.__app.explore.state;
745	+    const pin = () => { s.pos.set(B.x, B.y, B.z); s.yaw = 0; s.bank = 0; requestAnimationFrame(pin); };
