750	+  await frames(page, 40);   // camera bám ổn định
751	+  const c0 = await calls();
752	+
753	+  ['Ann', 'Binh', 'Chi', 'Dung'].forEach((n, i) => bots.push(bot(n, 90 + i * 20, (i - 1.5) * 18)));
754	+  await page.waitForFunction(() => [0, 1, 2, 3, 4].filter(i => window.__app.multi.remotes.slotState(i)).length === 4, null, { timeout: 60000 });
755	+  await frames(page, 20);
756	+  const info = await page.evaluate(() => {
757	+    const A = window.__app, R = A.multi.remotes, out = { slots: [], maps: [], labels: [], below: [], roster: null };
758	+    for (let i = 0; i < 5; i++) {
