768	+    }
769	+    out.roster = document.getElementById('exMpRoster').innerText;
770	+    return out;
771	+  });
772	+  check('4 bot bay: exRemotes có 4 dù', info.slots.length === 4);
773	+  check('4 màu khác nhau (4 bản đồ màu riêng: ' + info.maps.map((m) => m.length).join('/') + ')', new Set(info.maps).size === 4);
