786	+  check(`Bot đóng kết nối: dù biến mất (còn ${after.n}), roster còn 4 người bay (3 bot + mình), nhãn còn ${after.vis}`, after.n === 3 && /4\/5/.test(after.roster) && !after.roster.includes('Dung') && after.vis === 3);
787	+
788	+  check('console không lỗi', P.errors.length === 0);
789	+  if (P.errors.length) console.log(P.errors.join('\n'));
790	+} catch (e) {
791	+  check('ngoại lệ: ' + e.message, false);
792	+} finally {
793	+  bots.forEach((b) => b.close());
794	+  try { await browser?.close(); } catch { /* bỏ qua */ }
795	+  try { srv?.close(); } catch { /* bỏ qua */ }
